// Member money is stored in cents; balance is derived from immutable transactions.
export function memberBalance(m){return m.transactions.reduce((n,t)=>n+(t.type==='recharge'?t.amount+t.gift:-t.amount),0);}
export function searchMembers(members,query){const q=query.trim().toLowerCase();if(!q)return [];const digits=/^\d+$/.test(q);return members.filter(m=>digits?m.phone.includes(q):m.name.toLowerCase().includes(q)).sort((a,b)=>(digits?Number(b.phone.endsWith(q))-Number(a.phone.endsWith(q)):0)||a.name.localeCompare(b.name,'zh-CN')||a.phone.localeCompare(b.phone));}
const money=n=>Number.isSafeInteger(n)&&n>=0&&n<=99999999999;
export function validateMembers(rows){if(!Array.isArray(rows))throw Error('会员数据无效');const ids=new Set(),phones=new Set(),txids=new Set();for(const m of rows){if(!m||typeof m.id!=='string'||ids.has(m.id)||typeof m.name!=='string'||!m.name.trim()||m.name.length>80||!/^\d{6,20}$/.test(m.phone)||phones.has(m.phone)||(!Array.isArray(m.transactions)||m.transactions.length===0)||!Number.isFinite(Date.parse(m.createdAt)))throw Error('会员姓名、号码或记录无效');ids.add(m.id);phones.add(m.phone);let balance=0;for(const [index,t] of m.transactions.entries()){if(!t||typeof t.id!=='string'||!t.id||txids.has(t.id)||!['recharge','spend'].includes(t.type)||!money(t.amount)||!money(t.gift)||!Number.isFinite(Date.parse(t.at))||typeof t.note!=='string'||t.note.length>500)throw Error('会员流水无效');txids.add(t.id);if(t.type==='recharge'){if(t.amount<(index===0?3000:1000))throw Error('首充30元起，续充10元起');balance+=t.amount+t.gift;}else {if(index===0||t.amount<=0||t.gift!==0)throw Error('消费流水无效');balance-=t.amount;}if(!Number.isSafeInteger(balance)||balance<0)throw Error('会员余额或流水不一致');}}return rows;}
export function memberCommand(input,cmd,now=Date.now()){
 const rows=structuredClone(input||[]),at=new Date(now).toISOString();
 if(cmd.type==='create'){if(rows.some(m=>m.id===cmd.id))return rows;rows.push({id:cmd.id,name:cmd.name.trim(),phone:cmd.phone.trim(),createdAt:at,transactions:[{id:cmd.transactionId,type:'recharge',amount:cmd.amount,gift:cmd.gift??Math.round(cmd.amount/10),note:cmd.note||'',at}]});}
 else {const m=rows.find(m=>m.id===cmd.id);if(!m)throw Error('会员不存在');if(cmd.type==='edit'){m.name=cmd.name.trim();m.phone=cmd.phone.trim();}else{if(m.transactions.some(t=>t.id===cmd.transactionId))return rows;if(cmd.type==='spend'&&cmd.amount>memberBalance(m))throw Error('会员余额不足，不能消费');if(!['recharge','spend'].includes(cmd.type))throw Error('未知会员操作');m.transactions.push({id:cmd.transactionId,type:cmd.type,amount:cmd.amount,gift:cmd.type==='recharge'?(cmd.gift??Math.round(cmd.amount/10)):0,note:cmd.note||'',at});}}
 return validateMembers(rows);
}
